// ===== CONFIGURAÇÃO =====
const EVOLUTION_URL = 'http://evolution-api:8080';  // rede Docker (sem barra no final)
const INSTANCIA     = encodeURIComponent('NOME_DA_INSTANCIA');   // nome EXATO da instância na Evolution
const MODO_TESTE    = true;            // TESTE: envia só para o NUMERO_TESTE. Mude para false ao publicar
const NUMERO_TESTE  = ''; // recebe o RELATÓRIO (e, se MODO_TESTE=true, todas as mensagens)
const IGNORAR_DATA_HORA = true;        // TESTE: roda a qualquer hora. Mude para false ao publicar
const LIMITE_TESTE  = 3;               // só vale com MODO_TESTE=true (0 = sem limite)
const RELATORIO_POR_ENVIO = false;   // true = manda relatório no NUMERO_TESTE após cada disparo (o semanal vai no grupo)
// =========================

// Na execução do relatório semanal, este ramo não faz nada
const rodou = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const SEMANAL = rodou('Toda segunda 9h');
if (SEMANAL) return [];

const MESES = ['JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'];
const agora = $now.setZone('America/Sao_Paulo');
const dia = agora.day, hora = agora.hour;

if (!IGNORAR_DATA_HORA && (dia > 15 || hora < 9 || hora >= 17)) return [];

const colunaMes = MESES[agora.month - 1];
const ref = agora.minus({ months: 1 });
const mesRef = MESES[ref.month - 1].toLowerCase() + '/' + ref.year;
const mesNome = MESES[ref.month - 1].toLowerCase();

let texto;
if (dia <= 5) texto = (e) => `Olá, ${e}! Tudo bem? Aqui é da [SUA EMPRESA]. Estamos entrando em contato para solicitar o acesso para gerar o arquivo XML do mês de ${mesNome}, Obrigado!\n\nEnvie o acesso do TeamViewer para podermos acessar o sistema e gerar o XML.`;
else if (dia <= 10) texto = (e) => `Olá, ${e}! Ainda não recebemos o acesso para gerar o arquivo XML do mês de ${mesNome}. Consegue nos liberar até o dia 15 para não atrasar? Qualquer dúvida, estamos à disposição. Obrigado!\n\nEnvie o acesso do TeamViewer para podermos acessar o sistema e gerar o XML.`;
else texto = (e) => `Olá, ${e}! O prazo para liberar o acesso e gerarmos o arquivo XML do mês de ${mesNome} termina no dia 15. Sem o acesso, o processo pode atrasar. Pode nos liberar hoje, por favor? Obrigado!\n\nEnvie o acesso do TeamViewer para podermos acessar o sistema e gerar o XML.`;

const isTrue = (v) => v === true || ['TRUE','VERDADEIRO','1','SIM'].includes(String(v ?? '').trim().toUpperCase());
const isFalse = (v) => v === false || v === null || v === undefined || ['FALSE','FALSO','0','','NÃO','NAO'].includes(String(v).trim().toUpperCase());

const linhas = $input.all().map(i => i.json);
if (linhas.length && !(colunaMes in linhas[0])) {
  throw new Error(`Coluna ${colunaMes} não encontrada na planilha.`);
}

const resumo = { data: agora.toFormat('dd/MM/yyyy HH:mm'), coluna: colunaMes, mesRef, total: 0, jaEnviaram: 0, pulados: [] };
const envios = [];
const vistos = new Set();

for (const l of linhas) {
  const empresa = String(l['EMPRESA'] ?? '').trim();
  if (!empresa || /^(enviados no m|pendentes)/i.test(empresa)) continue;
  resumo.total++;
  const st = l[colunaMes];
  if (isTrue(st)) { resumo.jaEnviaram++; continue; }
  if (!isFalse(st)) { resumo.pulados.push(`${empresa} (status duvidoso: ${st})`); continue; }

  const nums = String(l['WHATSAPP'] ?? '').split('/').map(n => n.replace(/\D/g, '')).filter(Boolean);
  if (!nums.length) { resumo.pulados.push(`${empresa} (sem telefone)`); continue; }

  for (let n of nums) {
    if (!n.startsWith('55')) n = '55' + n;
    if (n.length < 12 || n.length > 13) { resumo.pulados.push(`${empresa} (número inválido: ${n})`); continue; }
    if (vistos.has(n)) continue;
    vistos.add(n);
    envios.push({ empresa, numero: n, destino: MODO_TESTE ? NUMERO_TESTE : n, texto: (MODO_TESTE ? `[TESTE → ${n}] ` : '') + texto(empresa) });
  }
}

const lista = (MODO_TESTE && LIMITE_TESTE > 0) ? envios.slice(0, LIMITE_TESTE) : envios;
if (lista.length < envios.length) resumo.pulados.push(`${envios.length - lista.length} envio(s) não feitos por causa do LIMITE_TESTE`);

return lista.map(e => ({ json: { ...e, url: EVOLUTION_URL, instancia: INSTANCIA, modoTeste: MODO_TESTE, numeroTeste: NUMERO_TESTE, relatorioPorEnvio: RELATORIO_POR_ENVIO, resumo } }));

const itens = $input.all().map(i => i.json);
const base = $('Montar lista de cobrança').first().json;
if (!base.relatorioPorEnvio) return [];
const r = base.resumo;
const ok = itens.filter(i => i.ok);
const erro = itens.filter(i => !i.ok);
let msg = `*Relatório cobrança XML* ${base.modoTeste ? '(MODO TESTE)' : ''}
` +
  `Data: ${r.data}
Referência: ${r.mesRef} (coluna ${r.coluna})

` +
  `Total de clientes: ${r.total}
Já enviaram: ${r.jaEnviaram}
Cobrados hoje: ${ok.length}
`;
if (ok.length) msg += `
*Cobrados:*
` + ok.map(i => `• ${i.empresa} - ${i.numero}`).join('
') + '
';
const pulados = [...r.pulados, ...erro.map(i => `${i.empresa} - ${i.numero} (erro ${i.status}: ${i.detalhe})`)];
if (pulados.length) msg += `
*Pulados/erros:*
` + pulados.map(p => `• ${p}`).join('
');
return [{ json: { url: base.url, instancia: base.instancia, destino: base.numeroTeste, texto: msg } }];

// ===== CONFIGURAÇÃO DO RELATÓRIO SEMANAL =====
const EVOLUTION_URL = 'http://evolution-api:8080';          // rede Docker (sem barra no final)
const INSTANCIA     = encodeURIComponent('NOME_DA_INSTANCIA');   // nome EXATO da instância na Evolution
const GRUPO_ID      = 'SEU_GRUPO_WHATSAPP_ID';       // ID do grupo (GET /group/fetchAllGroups/{instancia})
// =============================================

// Só roda no gatilho semanal (segunda 9h)
const rodou = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const SEMANAL = rodou('Toda segunda 9h');
if (!SEMANAL) return [];

const MESES = ['JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'];
const agora = $now.setZone('America/Sao_Paulo');
const colunaMes = MESES[agora.month - 1];
const ref = agora.minus({ months: 1 });
const mesRef = MESES[ref.month - 1].toLowerCase() + '/' + ref.year;

const isTrue = (v) => v === true || ['TRUE','VERDADEIRO','1','SIM'].includes(String(v ?? '').trim().toUpperCase());
const isFalse = (v) => v === false || v === null || v === undefined || ['FALSE','FALSO','0','','NÃO','NAO'].includes(String(v).trim().toUpperCase());

const linhas = $input.all().map(i => i.json);
if (linhas.length && !(colunaMes in linhas[0])) throw new Error(`Coluna ${colunaMes} não encontrada na planilha.`);

let total = 0, jaEnviaram = 0;
const pendentes = [], duvidosos = [];
for (const l of linhas) {
  const empresa = String(l['EMPRESA'] ?? '').trim();
  if (!empresa || /^(enviados no m|pendentes)/i.test(empresa)) continue;
  total++;
  const st = l[colunaMes];
  if (isTrue(st)) jaEnviaram++;
  else if (isFalse(st)) pendentes.push(empresa);
  else duvidosos.push(`${empresa} (status: ${st})`);
}

let msg = `*Relatório semanal - XML pendentes*\n` +
  `Data: ${agora.toFormat('dd/MM/yyyy')}\nReferência: ${mesRef} (coluna ${colunaMes})\n\n` +
  `Total de clientes: ${total}\nJá enviaram: ${jaEnviaram}\nFaltam enviar: ${pendentes.length}\n`;
msg += pendentes.length
  ? `\n*Faltam enviar:*\n` + pendentes.map((p, i) => `${i + 1}. ${p}`).join('\n')
  : `\nTodos os clientes já enviaram o XML deste mês. ✅`;
if (duvidosos.length) msg += `\n\n*Verificar na planilha:*\n` + duvidosos.map(d => `• ${d}`).join('\n');

return [{ json: { url: EVOLUTION_URL, instancia: INSTANCIA, destino: GRUPO_ID, texto: msg } }];

// ===== AUTENTICAÇÃO MICROSOFT (certificado) =====
const TENANT_ID  = 'SEU_TENANT_ID';           // Directory (tenant) ID do Entra ID
const CLIENT_ID  = 'SEU_CLIENT_ID';           // Application (client) ID do app
const THUMBPRINT = 'SEU_THUMBPRINT_SHA1';     // thumbprint SHA1 do certificado (40 caracteres hex)
const KEY_PATH   = '/home/node/.n8n/chave-privada.pem'; // chave privada dentro do container (node:node, 600)
// =================================================
const fs = require('fs');
const crypto = require('crypto');

const b64url = (b) => Buffer.from(b).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
const thumb = THUMBPRINT.replace(/[^0-9a-f]/gi, '');
if (thumb.length !== 40) throw new Error('THUMBPRINT inválido: precisa ter 40 caracteres hexadecimais.');

const tokenUrl = `https://login.microsoftonline.com/${TENANT_ID}/oauth2/v2.0/token`;
const agora = Math.floor(Date.now() / 1000);
const header  = { alg: 'RS256', typ: 'JWT', x5t: b64url(Buffer.from(thumb, 'hex')) };
const payload = { aud: tokenUrl, iss: CLIENT_ID, sub: CLIENT_ID, jti: crypto.randomUUID(), nbf: agora - 60, iat: agora, exp: agora + 600 };

const dados = b64url(JSON.stringify(header)) + '.' + b64url(JSON.stringify(payload));
const assinatura = crypto.createSign('RSA-SHA256').update(dados).sign(fs.readFileSync(KEY_PATH, 'utf8'));

return [{ json: { tokenUrl, clientId: CLIENT_ID, assertion: dados + '.' + b64url(assinatura) } }];
